/**
 * Documentation generated by Gemini
 * Purpose: Represents the user profile state lifecycle across the application session.
 * Role / Design Pattern: State model (Sealed Interface) representing Loading, Ready, Deleted, and Failed states.
 * Outstanding Issues: None.
 */
package com.example.campsitelottery

/**
 * Where the current device's profile is in its lifecycle. Held at the app level by
 * [CampsiteLotteryApp] and passed to the screens that need the current user.
 */
sealed interface UserState {

    /** The profile is still being fetched or created. */
    data object Loading : UserState

    /**
     * Documentation generated by Gemini
     * The profile is loaded.
     *
     * @property user Loaded user domain entity.
     */
    data class Ready(val user: User) : UserState

    /**
     * The user deleted their profile this session. A new empty profile is created
     * the next time the app launches, or when they choose to create one.
     */
    data object Deleted : UserState

    /**
     * Documentation generated by Gemini
     * The profile could not be loaded; [message] says why.
     *
     * @property message Descriptive failure error message.
     */
    data class Failed(val message: String) : UserState
}
